"use strict";
/* ============================================================
 * 我蛇了 IM SNAKE — 开场演出数据（window.INTRO_SCENE）
 * ------------------------------------------------------------
 * 播放器在 index.html 内（startIntro / updateIntro / drawIntroOverlay /
 * introLines），本文件只提供数据，禁止任何 DOM / 定时器逻辑。
 * 赋值目标做浏览器/无头测试双兼容：有 window 挂 window，否则挂 globalThis
 * （引擎侧 introScene() 对 window 缺失已有 try/catch 兜底）。
 *
 * 时间轴：黑屏 fadeIn 秒内渐亮 → 蛇以 75% 速向右爬到 walkEndX 停下
 *         → 玩家点击 / 空格逐句推进 lines → 台词放完自动进第一关。
 *
 * 走廊设计（网格矩形 [x,y,w,h]，世界 72x48，出生点 6.5,24.5）：
 *   - 内部通道 = 行 y22~y24，共 3 格宽，从 x=1 延伸到 x=29；
 *   - 蛇尾初始盘绕在 x1.5~5.5，因此通道左端做成一个出生小室
 *     （延伸到 x=1），避免尾巴穿墙；
 *   - 两处“微折”只侵占第 22 行，永不遮挡 y23/y24 直行道：
 *     ① x15 顶部岩垂收窄成 2 格 ② x24 单块坠石二次挤压；
 *   - 下壁在 x19~22 留缺口并用底板封死，形成向下 4 格深的
 *     死胡同凹龛，加上右端 x30 尽头墙，营造狭长探秘感。
 * ============================================================ */
(typeof window!=="undefined"?window:globalThis).INTRO_SCENE={
  fadeIn:1.4,
  walkEndX:26,
  corridorRects:[
    [ 0,17,32, 5],  // 上壁 y17~21，横贯全场
    [ 0,25,19, 5],  // 下壁左段 y25~29，到 x18 为止
    [23,25, 9, 5],  // 下壁右段，与左段之间留出 x19~22 凹龛口
    [19,29, 4, 1],  // 凹龛底封板：向下死胡同的底
    [ 0,22, 1, 3],  // 左端帽：封住出生小室左侧（行 y22~24）
    [30,22, 2, 3],  // 右端帽：走廊尽头墙（行 y22~24）
    [15,22, 2, 1],  // 微折①：顶部岩垂，通道在此收窄成 2 格
    [24,22, 1, 1],  // 微折②：临近尽头的单块坠石
  ],
  /* 规则：≤4 句、每句 ≤16 个汉字；前两句为固定文本。
   * 演出节奏与音画配合设想见 STORY_INTRO.md §1。 */
  lines:[
    "这里是哪里？我怎么睡着了",
    "……不管了，先往前走吧",
    "等等，我的手呢？！",
    "不会吧……我真的蛇了？！",
  ],
};
